"""Run against fixtures generated by tests/generators/generate_models.py."""

import gc
import json
import os
from concurrent.futures import ThreadPoolExecutor
from contextlib import nullcontext
from pathlib import Path

import lrt as lr
import numpy as np
import pytest

FIXTURES = Path(os.environ.get("LEAPP_TRITON_FIXTURES", "target/triton-fixtures"))
CUDA = os.environ.get("LEAPP_TEST_CUDA") == "1"
ENGINE = os.environ.get("LEAPP_TEST_ENGINE", "triton")


def open_session(name="feedback", device="cpu", **options):
    options.setdefault("engine", ENGINE)
    return lr.Session.open(
        lr.Bundle.open(FIXTURES / f"{name}.yaml"),
        lr.SessionOptions(device=device, **options),
    )


def step(session, value=1):
    return session.run(
        {"accumulator/observation": np.full(4, value, dtype=np.float32)}
    )["accumulator/next"]


@pytest.mark.parametrize(
    "options",
    [
        {},
        {"output_pool": lr.OutputPoolOptions(0)},
        {"output_pool": lr.OutputPoolOptions(1)},
    ],
    ids=["default", "no-cache", "one-entry"],
)
def test_output_lifetime_feedback_and_close(options):
    with open_session(**options) as rt:
        session = rt.new_session()
        tensor = step(session)
        view = np.from_dlpack(tensor)
        # NumPy versions differ in whether they expose writable DLPack leases.
        # Both must retain the result without exposing private feedback storage.
        if view.flags.writeable:
            view[:] = 99
            retained_value = 99
        else:
            with pytest.raises(ValueError):
                view[0] = 99
            with pytest.raises(ValueError):
                view.setflags(write=True)
            retained_value = 1
        mutable = view.copy()
        mutable[:] = 99
        np.testing.assert_array_equal(np.from_dlpack(step(session)), [2] * 4)
        np.testing.assert_array_equal(view, [retained_value] * 4)
        session.reset()
        np.testing.assert_array_equal(np.from_dlpack(step(session)), [1] * 4)
        assert view.shape == (4,)
        assert view.dtype == np.float32
        assert tensor.__dlpack_device__() == (1, 0)
    rt.close()
    np.testing.assert_array_equal(np.from_dlpack(step(session)), [2] * 4)
    peer = session.new_session()
    np.testing.assert_array_equal(np.from_dlpack(step(peer)), [1] * 4)
    peer.close()
    session.close()
    for operation in (
        rt.new_session,
        session.reset,
        lambda session=session: step(session),
    ):
        with pytest.raises(lr.RuntimeError) as error:
            operation()
        assert error.value.code == lr.ErrorCode.INVALID_ARGUMENT
        assert error.value.phase == "execute"
    assert rt.info().model_names() == ["accumulator"]
    del tensor, rt, session
    gc.collect()
    np.testing.assert_array_equal(view, [retained_value] * 4)


def test_negative_cache_limit_is_rejected():
    with pytest.raises(OverflowError):
        open_session(output_pool=lr.OutputPoolOptions(-1))


def test_unknown_engine_is_rejected():
    with pytest.raises(
        ValueError, match="unknown engine 'unknown'; expected 'triton' or 'native'"
    ):
        open_session(engine="unknown")


@pytest.mark.skipif(ENGINE != "triton", reason="default engine is Triton")
def test_default_engine():
    assert lr.SessionOptions().engine == "triton"
    bundle = lr.Bundle.open(FIXTURES / "feedback.yaml")
    for options in [None, lr.SessionOptions()]:
        with lr.Session.open(bundle, options) as session:
            np.testing.assert_array_equal(np.from_dlpack(step(session)), [1] * 4)


def test_dlpack_exports_alias_and_retain_storage():
    torch = pytest.importorskip("torch")
    with open_session() as rt:
        session = rt.new_session()
        tensor = step(session)
        first = torch.from_dlpack(tensor)
        second = torch.from_dlpack(tensor)
        assert first.data_ptr() == second.data_ptr()
        first.fill_(99)
        assert second.tolist() == [99] * 4
        tensor.__dlpack__(copy=False)
        with pytest.raises(BufferError, match="materialize"):
            tensor.__dlpack__(copy=True)
    del tensor, rt, session
    gc.collect()
    assert second.tolist() == [99] * 4


def test_dlpack_inputs_and_validation():
    torch = pytest.importorskip("torch")
    with open_session("dynamic") as rt:
        session = rt.new_session()
        source = torch.arange(8, dtype=torch.float32)
        with pytest.raises((BufferError, RuntimeError), match="grad"):
            session.run({"dynamic/input": source.clone().requires_grad_()})
        np.testing.assert_array_equal(
            np.from_dlpack(
                session.run({"dynamic/input": source[2:6]})["dynamic/output"]
            ),
            np.arange(2, 6, dtype=np.float32),
        )
        for bad in (np.ones(4, dtype=">f4"),):
            with pytest.raises(BufferError):
                session.run({"dynamic/input": bad})
        with pytest.raises(lr.RuntimeError) as error:
            session.run({"dynamic/input": np.ones(4, dtype=np.int32)})
        assert error.value.code == lr.ErrorCode.INVALID_ARGUMENT
        with pytest.raises(KeyError):
            session.run({"dynamic/input": source})["missing"]

        class DuplicateInputs:
            def items(self):
                return [("dynamic/input", source)] * 2

        with pytest.raises(ValueError, match="duplicate input"):
            session.run(DuplicateInputs())
        assert len(session.run({"dynamic/input": source})) == 1
        for shape in (0, 1, 9):
            result = session.run({"dynamic/input": np.ones(shape, dtype=np.float32)})
            assert np.from_dlpack(result["dynamic/output"]).shape == (shape,)


def test_serialization_and_concurrent_sessions():
    with open_session() as rt, ThreadPoolExecutor(max_workers=4) as pool:
        session = rt.new_session()
        values = list(
            pool.map(lambda _: float(np.from_dlpack(step(session))[0]), range(12))
        )
        assert sorted(values) == list(range(1, 13))
        sessions = [rt.new_session() for _ in range(4)]
        values = list(pool.map(lambda s: float(np.from_dlpack(step(s))[0]), sessions))
        assert values == [1] * 4
        future = pool.submit(lambda: [step(session) for _ in range(20)])
        session.close()
        try:
            future.result(timeout=20)
        except lr.RuntimeError as error:
            assert error.code == lr.ErrorCode.INVALID_ARGUMENT


@pytest.mark.skipif(not CUDA, reason="set LEAPP_TEST_CUDA=1")
@pytest.mark.parametrize("output_device", ["cpu", "pinned", "cuda:0"])
def test_cuda_streams_and_output_placement(output_device):
    cp = pytest.importorskip("cupy")
    torch = pytest.importorskip("torch")
    with open_session(device="cuda:0", output_device=output_device) as rt:
        session = rt.new_session()
        stream = cp.cuda.Stream(non_blocking=True)
        with stream:
            obs = cp.arange(4, dtype=cp.float32)
            obs += 1
            result = session.run({"accumulator/observation": obs})
        tensor = result["accumulator/next"]
        assert (
            tensor.__dlpack_device__()
            == {"cpu": (1, 0), "pinned": (3, 0), "cuda:0": (2, 0)}[output_device]
        )
        if output_device == "cuda:0":
            with cp.cuda.Stream(non_blocking=True):
                copied = cp.from_dlpack(tensor)
                shared = cp.from_dlpack(tensor)
                assert copied.data.ptr == shared.data.ptr
                copied[:] = 99
                np.testing.assert_array_equal(cp.asnumpy(shared), [99] * 4)
            with pytest.raises(BufferError):
                np.from_dlpack(tensor)
            torch_stream = torch.cuda.Stream()
            with torch.cuda.stream(torch_stream):
                value = torch.ones(4, dtype=torch.float32, device="cuda")
                value.mul_(2)
                next_result = session.run({"accumulator/observation": value})
            np.testing.assert_array_equal(
                cp.asnumpy(cp.from_dlpack(next_result["accumulator/next"])),
                [3, 4, 5, 6],
            )
        else:
            np.testing.assert_array_equal(np.from_dlpack(tensor), [1, 2, 3, 4])
        session.reset()
        with open_session(
            device="cuda:0", output_overrides={"accumulator/next": "cpu"}
        ) as host_session:
            result = step(host_session)
            assert result.__dlpack_device__() == (1, 0)


@pytest.mark.parametrize("output_device", ["cpu", "pinned", "cuda:0"])
def test_runtime_tensor_inputs(output_device):
    if output_device != "cpu" and (not CUDA):
        pytest.skip("set LEAPP_TEST_CUDA=1")
    with open_session("dynamic", output_device=output_device) as rt:
        session = rt.new_session()
        result = session.run(
            {"dynamic/input": np.array([7], dtype=np.float32)},
        )
        retained = result["dynamic/output"]
        assert (
            retained.__dlpack_device__()
            == {"cpu": (1, 0), "pinned": (3, 0), "cuda:0": (2, 0)}[output_device]
        )
        for _ in range(8):
            result = session.run({"dynamic/input": result["dynamic/output"]})
            assert (
                result["dynamic/output"].__dlpack_device__()
                == retained.__dlpack_device__()
            )
        host_session = open_session("dynamic")
        host = host_session.run({"dynamic/input": result["dynamic/output"]})
        np.testing.assert_array_equal(np.from_dlpack(host["dynamic/output"]), [7])
        host = host_session.run({"dynamic/input": retained})
        np.testing.assert_array_equal(np.from_dlpack(host["dynamic/output"]), [7])


@pytest.mark.skipif(not CUDA, reason="set LEAPP_TEST_CUDA=1")
@pytest.mark.parametrize("device", ["cpu", "cuda:0"])
@pytest.mark.parametrize("legacy", [False, True])
def test_pinned_pytorch_input(device, legacy):
    torch = pytest.importorskip("torch")
    source = torch.arange(4, dtype=torch.float32, pin_memory=True)

    class LegacyProducer:
        def __dlpack_device__(self):
            return source.__dlpack_device__()

        def __dlpack__(self, *, stream=None):
            return source.__dlpack__(stream=stream)

    producer = LegacyProducer() if legacy else source
    with open_session("dynamic", device) as rt:
        result = rt.new_session().run({"dynamic/input": producer})
        np.testing.assert_array_equal(
            np.from_dlpack(result["dynamic/output"]), [0, 1, 2, 3]
        )
    assert source.is_pinned()
    torch.testing.assert_close(source, torch.arange(4, dtype=torch.float32))


@pytest.mark.skipif(not CUDA, reason="set LEAPP_TEST_CUDA=1")
@pytest.mark.parametrize("legacy", [False, True])
@pytest.mark.parametrize("fail", [False, True])
def test_dlpack_selects_producer_device_and_restores_caller(legacy, fail):
    torch = pytest.importorskip("torch")
    if torch.cuda.device_count() < 2:
        pytest.skip("requires two CUDA devices")
    original = torch.cuda.current_device()
    target = (original + 1) % torch.cuda.device_count()
    stream = torch.cuda.Stream(device=target)
    calls = []

    class Producer:
        def __dlpack_device__(self):
            return source.__dlpack_device__()

        def __dlpack__(self, *, stream, max_version=None):
            calls.append(torch.cuda.current_device())
            assert calls[-1] == target
            if legacy and max_version is not None:
                raise TypeError("max_version unsupported")
            if fail:
                raise ValueError("producer failed")
            return source.__dlpack__(stream=stream)

    with open_session("dynamic", f"cuda:{target}") as rt, torch.cuda.stream(stream):
        source = torch.ones(4, dtype=torch.float32, device=f"cuda:{target}")
        source.mul_(3)
        torch.cuda.set_device(original)
        if fail:
            with pytest.raises(ValueError, match="producer failed"):
                rt.new_session().run({"dynamic/input": Producer()})
        else:
            result = rt.new_session().run({"dynamic/input": Producer()})
            np.testing.assert_array_equal(
                np.from_dlpack(result["dynamic/output"]), [3] * 4
            )
        assert torch.cuda.current_device() == original
    assert calls == [target] * (2 if legacy else 1)
    assert torch.cuda.current_device() == original


@pytest.mark.parametrize("layout", ["slice", "reverse", "broadcast", "offset", "empty"])
def test_numpy_input_layouts(layout):
    source = np.arange(12, dtype=np.float32)
    views = {
        "slice": source[1::3],
        "reverse": source[::-1],
        "broadcast": np.broadcast_to(source[2:3], (4,)),
        "offset": source[2:6],
        "empty": source[:0],
    }
    value = views[layout]
    with open_session("dynamic") as rt:
        session = rt.new_session()
        if not value.flags.c_contiguous:
            with pytest.raises((lr.RuntimeError, BufferError)):
                session.run({"dynamic/input": value})
        result = session.run({"dynamic/input": np.array(value, copy=True, order="C")})
    np.testing.assert_array_equal(np.from_dlpack(result["dynamic/output"]), value)
    np.testing.assert_array_equal(source, np.arange(12, dtype=np.float32))


@pytest.mark.parametrize("device", ["cpu"] + (["cuda:0"] if CUDA else []))
@pytest.mark.parametrize("layout", ["slice", "broadcast", "offset", "empty"])
def test_pytorch_input_layouts(device, layout):
    torch = pytest.importorskip("torch")
    context = (
        torch.cuda.stream(torch.cuda.Stream(device=device))
        if device.startswith("cuda")
        else nullcontext()
    )
    with open_session("dynamic", device) as rt, context:
        source = torch.arange(12, dtype=torch.float32, device=device)
        source.mul_(3)
        views = {
            "slice": source[1::3],
            "broadcast": source[2:3].expand(4),
            "offset": source[2:6],
            "empty": source[:0],
        }
        value = views[layout]
        session = rt.new_session()
        if not value.is_contiguous():
            with pytest.raises(lr.RuntimeError, match="contiguous"):
                session.run({"dynamic/input": value})
        result = session.run({"dynamic/input": value.contiguous()})
        expected = value.cpu().numpy().copy()
    del views, value
    gc.collect()
    np.testing.assert_array_equal(np.from_dlpack(result["dynamic/output"]), expected)
    torch.testing.assert_close(source.cpu(), torch.arange(12, dtype=torch.float32) * 3)


