@pytest.mark.skipif(not CUDA, reason="set LEAPP_TEST_CUDA=1")
def test_generic_dlpack_reuses_handoff_and_drains_producer_errors():
    torch = pytest.importorskip("torch")
    values = torch.arange(4, dtype=torch.float32, device="cuda")
    done = torch.cuda.Event()
    addresses = []

    class Producer:
        fail = False

        def __dlpack_device__(self):
            return values.__dlpack_device__()

        def __dlpack__(self, *, stream, max_version=None):
            addresses.append(stream)
            with torch.cuda.stream(torch.cuda.ExternalStream(stream)):
                torch.cuda._sleep(10_000_000)
                done.record()
            if self.fail:
                raise ValueError("producer failed")
            return values.__dlpack__(stream=stream, max_version=max_version)

    producer = Producer()
    with open_session("dynamic", "cuda:0") as rt:
        session = rt.new_session()
        for _ in range(2):
            np.testing.assert_array_equal(
                np.from_dlpack(
                    session.run({"dynamic/input": producer})["dynamic/output"]
                ),
                np.arange(4, dtype=np.float32),
            )
        producer.fail = True
        with pytest.raises(ValueError, match="producer failed"):
            session.run({"dynamic/input": producer})
        assert done.query()
    assert len(set(addresses)) == 1


@pytest.mark.parametrize("device", ["cpu"] + (["cuda:0"] if CUDA else []))
def test_multiple_dlpack_outputs_and_retained_placements(device, tmp_path):
    torch = pytest.importorskip("torch")
    bundle = json.loads((FIXTURES / "policy.yaml").read_text())
    bundle["pipeline"]["outputs"]["policy"] = ["action", "echo"]
    for model in bundle["models"].values():
        parameters = model["parameters"]
        parameters["model_path"] = str((FIXTURES / parameters["model_path"]).resolve())
    (tmp_path / "policy.yaml").write_text(json.dumps(bundle))
    with open_session(tmp_path / "policy", device, output_device=device) as rt:
        session = rt.new_session()
        producer = (
            torch.cuda.stream(torch.cuda.Stream())
            if device.startswith("cuda")
            else nullcontext()
        )
        retained = []
        for offset in [0, 10]:
            with producer:
                # Contiguous slices can still have a nonzero storage offset.
                values = (
                    torch.arange(0, 5, dtype=torch.float32, device=device) + offset
                )[1:]
                bias = values * 10
                result = session.run(
                    {"preprocess/observation": values, "policy/bias": bias},
                )
                retained.append(result)
        # Retained results must survive later runs with different placement.
        host = np.arange(1, 5, dtype=np.float32)
        host_session = open_session(tmp_path / "policy", device)
        again = host_session.run(
            {"preprocess/observation": host, "policy/bias": host * 10}
        )
        np.testing.assert_array_equal(
            np.from_dlpack(again["policy/action"]), [14, 29, 46, 65]
        )
        for offset, result in zip([0, 10], retained, strict=True):
            original = torch.arange(1, 5, dtype=torch.float32) + offset
            expected = (original + 1) * torch.tensor([2, 3, 4, 5]) + original * 10
            copied = torch.from_dlpack(result["policy/action"])
            alias = torch.from_dlpack(result["policy/echo"])
            torch.testing.assert_close(copied.cpu(), expected)
            torch.testing.assert_close(alias.cpu(), original + 1 - original * 10)
    torch.testing.assert_close(
        values.cpu(), torch.arange(1, 5, dtype=torch.float32) + 10
    )


@pytest.mark.skipif(not CUDA, reason="set LEAPP_TEST_CUDA=1")
@pytest.mark.parametrize("fail", [None, "input", "iterator", "producer"])
def test_batch_waits_for_each_producer_stream_even_on_import_error(fail):
    torch = pytest.importorskip("torch")
    streams = [torch.cuda.Stream(), torch.cuda.Stream()]
    done = [torch.cuda.Event(), torch.cuda.Event()]
    values = [torch.empty(4, device="cuda"), torch.empty(4, device="cuda")]

    released = []

    class Producer:
        def __init__(self, index):
            self.index = index

        def __dlpack_device__(self):
            return values[self.index].__dlpack_device__()

        def __dlpack__(self, **kwargs):
            capsule = values[self.index].__dlpack__(**kwargs)
            if fail == "producer" and self.index == 1:
                raise ValueError("producer failed")
            return capsule

        def __del__(self):
            released.append(done[self.index].query())

    class Inputs:
        def items(self):
            for index, name in enumerate(["preprocess/observation", "policy/bias"]):
                with torch.cuda.stream(streams[index]):
                    torch.cuda._sleep(10_000_000)
                    values[index].fill_(index + 1)
                    done[index].record()
                    yield name, Producer(index)
            if fail == "input":
                yield "invalid", object()
            if fail == "iterator":
                raise ValueError("iterator failed")

    with open_session("policy", "cuda:0") as rt:
        session = rt.new_session()
        if fail:
            with pytest.raises(TypeError if fail == "input" else ValueError):
                session.run(Inputs())
        else:
            result = session.run(Inputs())
            np.testing.assert_array_equal(
                np.from_dlpack(result["policy/action"]), [6, 8, 10, 12]
            )
        assert all(event.query() for event in done)
        gc.collect()
        assert released == [True, True]
